	LIBVMDK_DISK_TYPE_VMFS_SPARSE_THIN
};

#define LIBVMDK_DISK_TYPE_2GB_EXTENT_FLAT	LIBVMDK_DISK_TYPE_FLAT_2GB_EXTENT
#define LIBVMDK_DISK_TYPE_2GB_EXTENT_SPARSE	LIBVMDK_DISK_TYPE_SPARSE_2GB_EXTENT

/* The compression methods
 */
enum LIBVMDK_COMPRESSION_METHODS
{
	LIBVMDK_COMPRESSION_METHOD_NONE		= 0,
	LIBVMDK_COMPRESSION_METHOD_DEFLATE	= 1
};

/* The extent access
 */
enum LIBVMDK_EXTENT_ACCESS
{
	LIBVMDK_EXTENT_ACCESS_NONE		= 1,
	LIBVMDK_EXTENT_ACCESS_READ		= 2,
	LIBVMDK_EXTENT_ACCESS_READ_WRITE	= 3,
};

/* The extent types
 */
enum LIBVMDK_EXTENT_TYPES
{
	LIBVMDK_EXTENT_TYPE_FLAT		= 1,
	LIBVMDK_EXTENT_TYPE_SPARSE		= 2,
	LIBVMDK_EXTENT_TYPE_VMFS_FLAT		= 3,
	LIBVMDK_EXTENT_TYPE_VMFS_SPARSE		= 4,
	LIBVMDK_EXTENT_TYPE_VMFS_RAW		= 5,
	LIBVMDK_EXTENT_TYPE_VMFS_RDM		= 6,
	LIBVMDK_EXTENT_TYPE_ZERO		= 7,
};

#endif /* !defined( _LIBVMDK_DEFINITIONS_H ) */

item.aggregated_output:
		 LIBCERROR_IO_ERROR_CLOSE_FAILED,
		 "%s: unable to close input handle.",
		 function );

		return( -1 );
	}
	return( 0 );
}

/* Prints the file information to a stream
 * Returns 1 if successful or -1 on error
 */
int info_handle_file_fprint(
     info_handle_t *info_handle,
     libcerror_error_t **error )
{
	system_character_t byte_size_string[ 16 ];

	libvmdk_extent_descriptor_t *extent_descriptor = NULL;
	system_character_t *value_string               = NULL;
	static char *function                          = "info_handle_file_fprint";
	size64_t extent_size                           = 0;
	size64_t media_size                            = 0;
	size_t value_string_size                       = 0;
	off64_t extent_offset                          = 0;
	uint32_t content_identifier                    = 0;
	int disk_type                                  = 0;
	int extent_index                               = 0;
	int extent_type                                = 0;
	int number_of_extents                          = 0;
	int result                                     = 0;

	if( info_handle == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid info handle.",
		 function );

		return( -1 );
	}
	fprintf(
	 info_handle->notify_stream,
	 "VMware Virtual Disk (VMDK) information:\n" );

	if( libvmdk_handle_get_disk_type(
	     info_handle->input_handle,
	     &disk_type,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve disk type.",
		 function );

		goto on_error;
	}
	fprintf(
	 info_handle->notify_stream,
	 "\tDisk type\t\t\t: " );

	switch( disk_type )
	{
		case LIBVMDK_DISK_TYPE_FLAT_2GB_EXTENT:
			fprintf(
			 info_handle->notify_stream,
			 "2GB extent flat" );
			break;

		case LIBVMDK_DISK_TYPE_SPARSE_2GB_EXTENT:
			fprintf(
			 info_handle->notify_stream,
			 "2GB extent sparse" );
			break;

		case LIBVMDK_DISK_TYPE_CUSTOM:
			fprintf(
			 info_handle->notify_stream,
			 "Custom" );
			break;

		case LIBVMDK_DISK_TYPE_DEVICE:
			fprintf(
			 info_handle->notify_stream,
			 "Device" );
			break;

		case LIBVMDK_DISK_TYPE_DEVICE_PARITIONED:
			fprintf(
			 info_handle->notify_stream,
			 "Device paritioned" );
			break;

		case LIBVMDK_DISK_TYPE_MONOLITHIC_FLAT:
			fprintf(
			 info_handle->notify_stream,
			 "Monolithic flat" );
			break;

		case LIBVMDK_DISK_TYPE_MONOLITHIC_SPARSE:
			fprintf(
			 info_handle->notify_stream,
			 "Monolithic sparse" );
			break;

		case LIBVMDK_DISK_TYPE_STREAM_OPTIMIZED:
			fprintf(
			 info_handle->notify_stream,
			 "Stream optimized" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_FLAT:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS flat" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_FLAT_PRE_ALLOCATED:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS flat (pre-allocated)" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_FLAT_ZEROED:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS flat (zeroed)" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_RAW:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS RAW" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_RDM:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS RDM" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_RDMP:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS RDMP" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_SPARSE:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS sparse" );
			break;

		case LIBVMDK_DISK_TYPE_VMFS_SPARSE_THIN:
			fprintf(
			 info_handle->notify_stream,
			 "VMFS sparse (thin)" );
			break;

		default:
			fprintf(
			 info_handle->notify_stream,
			 "Unknown" );
			break;
	}
	fprintf(
	 info_handle->notify_stream,
	 "\n" );

	if( libvmdk_handle_get_media_size(
	     info_handle->input_handle,
	     &media_size,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve media size.",
		 function );

		goto on_error;
	}
	result = byte_size_string_create(
	          byte_size_string,
	          16,
	          media_size,
	          BYTE_SIZE_STRING_UNIT_MEBIBYTE,
	          NULL );

	if( result == 1 )
	{
		fprintf(
		 info_handle->notify_stream,
		 "\tMedia size\t\t\t: %" PRIs_SYSTEM " (%" PRIu64 " bytes)\n",
		 byte_size_string,
		 media_size );
	}
	else
	{
		fprintf(
		 info_handle->notify_stream,
		 "\tMedia size\t\t\t: %" PRIu64 " bytes\n",
		 media_size );
	}
	if( libvmdk_handle_get_content_identifier(
	     info_handle->input_handle,
	     &content_identifier,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve content identifier.",
		 function );

		goto on_error;
	}
	fprintf(
	 info_handle->notify_stream,
	 "\tContent identifier\t\t: 0x%08" PRIx32 "\n",
	 content_identifier );

	result = libvmdk_handle_get_parent_content_identifier(
	          info_handle->input_handle,
	          &content_identifier,
	          error );

	if( result == -1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve parent content identifier.",
		 function );

		goto on_error;
	}
	else if( result != 0 )
	{
		fprintf(
		 info_handle->notify_stream,
		 "\tParent content identifier\t: 0x%08" PRIx32 "\n",
		 content_identifier );
	}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
	result = libvmdk_handle_get_utf16_parent_filename_size(
	          info_handle->input_handle,
	          &value_string_size,
	          error );
#else
	result = libvmdk_handle_get_utf8_parent_filename_size(
	          info_handle->input_handle,
	          &value_string_size,
	          error );
#endif
	if( result == -1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve parent filename size.",
		 function );

		goto on_error;
	}
	else if( result != 0 )
	{
		if( ( value_string_size == 0 )
		 || ( value_string_size > ( (size_t) MEMORY_MAXIMUM_ALLOCATION_SIZE / sizeof( system_character_t ) ) ) )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_VALUE_OUT_OF_BOUNDS,
			 "%s: invalid parent filename size value out of bounds.",
			 function );

			goto on_error;
		}
		value_string = system_string_allocate(
		                value_string_size );

		if( value_string == NULL )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_MEMORY,
			 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
			 "%s: unable to create parent filename string.",
			 function );

			goto on_error;
		}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
		result = libvmdk_handle_get_utf16_parent_filename(
		          info_handle->input_handle,
		          (uint16_t *) value_string,
		          value_string_size,
		          error );
#else
		result = libvmdk_handle_get_utf8_parent_filename(
		          info_handle->input_handle,
		          (uint8_t *) value_string,
		          value_string_size,
		          error );
#endif
		if( result != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve parent filename.",
			 function );

			goto on_error;
		}
		fprintf(
		 info_handle->notify_stream,
		 "\tParent filename\t\t\t: %" PRIs_SYSTEM "\n",
		 value_string );

		memory_free(
		 value_string );

		value_string = NULL;
	}
	if( libvmdk_handle_get_number_of_extents(
	     info_handle->input_handle,
	     &number_of_extents,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve number of extents.",
		 function );

		goto on_error;
	}
	fprintf(
	 info_handle->notify_stream,
	 "\tNumber of extents\t\t: %d\n",
	 number_of_extents );

	fprintf(
	 info_handle->notify_stream,
	 "\n" );

	for( extent_index = 0;
	     extent_index < number_of_extents;
	     extent_index++ )
	{
		fprintf(
		 info_handle->notify_stream,
		 "Extent: %d\n",
		 extent_index + 1 );

		if( libvmdk_handle_get_extent_descriptor(
		     info_handle->input_handle,
		     extent_index,
		     &extent_descriptor,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve extent: %d descriptor.",
			 function,
			 extent_index );

			goto on_error;
		}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
		result = libvmdk_extent_descriptor_get_utf16_filename_size(
		          extent_descriptor,
		          &value_string_size,
		          error );
#else
		result = libvmdk_extent_descriptor_get_utf8_filename_size(
		          extent_descriptor,
		          &value_string_size,
		          error );
#endif
		if( result == -1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve extent: %d descriptor filename size.",
			 function,
			 extent_index );

			goto on_error;
		}
		else if( result != 0 )
		{
			if( ( value_string_size == 0 )
			 || ( value_string_size > ( (size_t) MEMORY_MAXIMUM_ALLOCATION_SIZE / sizeof( system_character_t ) ) ) )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_VALUE_OUT_OF_BOUNDS,
				 "%s: invalid filename size value out of bounds.",
				 function );

				goto on_error;
			}
			value_string = system_string_allocate(
			                value_string_size );

			if( value_string == NULL )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_MEMORY,
				 LIBCERROR_MEMORY_ERROR_INSUFFICIENT,
				 "%s: unable to create filename string.",
				 function );

				goto on_error;
			}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
			result = libvmdk_extent_descriptor_get_utf16_filename(
			          extent_descriptor,
				  (uint16_t *) value_string,
				  value_string_size,
				  error );
#else
			result = libvmdk_extent_descriptor_get_utf8_filename(
			          extent_descriptor,
				  (uint8_t *) value_string,
				  value_string_size,
				  error );
#endif
			if( result != 1 )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_RUNTIME,
				 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
				 "%s: unable to retrieve extent: %d descriptor filename.",
				 function,
				 extent_index );

				goto on_error;
			}
			fprintf(
			 info_handle->notify_stream,
			 "\tFilename\t\t\t: %" PRIs_SYSTEM "\n",
			 value_string );

			memory_free(
			 value_string );

			value_string = NULL;
		}
		if( libvmdk_extent_descriptor_get_type(
		     extent_descriptor,
		     &extent_type,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve extent: %d descriptor type.",
			 function,
			 extent_index );

			goto on_error;
		}
		fprintf(
		 info_handle->notify_stream,
		 "\tType\t\t\t\t: " );

		switch( extent_type )
		{
			case LIBVMDK_EXTENT_TYPE_FLAT:
				fprintf(
				 info_handle->notify_stream,
				 "Flat" );
				break;

			case LIBVMDK_EXTENT_TYPE_SPARSE:
				fprintf(
				 info_handle->notify_stream,
				 "Sparse" );
				break;

			case LIBVMDK_EXTENT_TYPE_VMFS_FLAT:
				fprintf(
				 info_handle->notify_stream,
				 "VMFS flat" );
				break;

        		case LIBVMDK_EXTENT_TYPE_VMFS_SPARSE:
				fprintf(
				 info_handle->notify_stream,
				 "VMFS sparse" );
				break;

        		case LIBVMDK_EXTENT_TYPE_VMFS_RAW:
				fprintf(
				 info_handle->notify_stream,
				 "VMFS RAW" );
				break;

        		case LIBVMDK_EXTENT_TYPE_VMFS_RDM:
				fprintf(
				 info_handle->notify_stream,
				 "VMFS RDM" );
				break;

        		case LIBVMDK_EXTENT_TYPE_ZERO:
				fprintf(
				 info_handle->notify_stream,
				 "Zero" );
				break;

			default:
				fprintf(
				 info_handle->notify_stream,
				 "Unknown" );
				break;
		}
		fprintf(
		 info_handle->notify_stream,
		 "\n" );

		if( libvmdk_extent_descriptor_get_range(
		     extent_descriptor,
		     &extent_offset,
		     &extent_size,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve extent: %d descriptor range.",
			 function,
			 extent_index );

			goto on_error;
		}
		fprintf(
		 info_handle->notify_stream,
		 "\tStart offset\t\t\t: %" PRIi64 "\n",
		 extent_offset );

		result = byte_size_string_create(
		          byte_size_string,
		          16,
		          extent_size,
		          BYTE_SIZE_STRING_UNIT_MEBIBYTE,
		          NULL );

		if( result == 1 )
		{
			fprintf(
			 info_handle->notify_stream,
			 "\tSize\t\t\t\t: %" PRIs_SYSTEM " (%" PRIu64 " bytes)\n",
			 byte_size_string,
			 extent_size );
		}
		else
		{
			fprintf(
			 info_handle->notify_stream,
			 "\tSize\t\t\t\t: %" PRIu64 " bytes\n",
			 extent_size );
		}
		if( libvmdk_extent_descriptor_free(
		     &extent_descriptor,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_FINALIZE_FAILED,
			 "%s: unable to free extent: %d descriptor.",
			 function,
			 extent_index );

			goto on_error;
		}
		fprintf(
		 info_handle->notify_stream,
		 "\n" );
	}
	return( 1 );

on_error:
	if( extent_descriptor != NULL )
	{
		libvmdk_extent_descriptor_free(
		 &extent_descriptor,
		 NULL );
	}
	if( value_string != NULL )
	{
		memory_free(
		 value_string );
	}
	return( -1 );
}

 * Returns 1 if successful, 0 if not or -1 on error
 */
int mount_handle_open(
     mount_handle_t *mount_handle,
     system_character_t * const * filenames,
     int number_of_filenames,
     libcerror_error_t **error )
{
	libvmdk_handle_t *vmdk_handle      = NULL;
	system_character_t *basename_end   = NULL;
	static char *function              = "mount_handle_open";
	size_t basename_length             = 0;
	size_t filename_length             = 0;
	uint32_t parent_content_identifier = 0;
	int disk_type                      = 0;
	int result                         = 0;

	if( mount_handle == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid mount handle.",
		 function );

		return( -1 );
	}
	if( filenames == NULL )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
		 "%s: invalid filenames.",
		 function );

		return( -1 );
	}
	if( number_of_filenames <= 0 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
		 LIBCERROR_ARGUMENT_ERROR_VALUE_OUT_OF_BOUNDS,
		 "%s: number of filenames value out of bounds.",
		 function );

		return( -1 );
	}
	filename_length = system_string_length(
	                   filenames[ 0 ] );

	basename_end = system_string_search_character_reverse(
	                filenames[ 0 ],
	                (system_character_t) LIBCPATH_SEPARATOR,
	                filename_length + 1 );

	if( basename_end != NULL )
	{
		basename_length = (size_t) ( basename_end - filenames[ 0 ] ) + 1;
	}
	if( basename_length > 0 )
	{
		if( mount_handle_set_basename(
		     mount_handle,
		     filenames[ 0 ],
		     basename_length,
		     error ) != 1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_SET_FAILED,
			 "%s: unable to set basename.",
			 function );

			goto on_error;
		}
	}
	if( libvmdk_handle_initialize(
	     &vmdk_handle,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_INITIALIZE_FAILED,
		 "%s: unable to initialize handle.",
		 function );

		goto on_error;
	}
#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
	result = libvmdk_handle_open_wide(
	          vmdk_handle,
	          filenames[ 0 ],
	          LIBVMDK_OPEN_READ,
	          error );
#else
	result = libvmdk_handle_open(
	          vmdk_handle,
	          filenames[ 0 ],
	          LIBVMDK_OPEN_READ,
	          error );
#endif
	if( result != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_IO,
		 LIBCERROR_IO_ERROR_OPEN_FAILED,
		 "%s: unable to open handle.",
		 function );

		goto on_error;
	}
	if( libvmdk_handle_get_disk_type(
	     vmdk_handle,
	     &disk_type,
	     error ) != 1 )
	{
		libcerror_error_set(
		 error,
		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
		 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
		 "%s: unable to retrieve disk type.",
		 function );

		goto on_error;
	}
	if( ( disk_type != LIBVMDK_DISK_TYPE_FLAT_2GB_EXTENT )
	 && ( disk_type != LIBVMDK_DISK_TYPE_SPARSE_2GB_EXTENT )
	 && ( disk_type != LIBVMDK_DISK_TYPE_MONOLITHIC_SPARSE )
	 && ( disk_type != LIBVMDK_DISK_TYPE_STREAM_OPTIMIZED )
	 && ( disk_type != LIBVMDK_DISK_TYPE_VMFS_FLAT )
	 && ( disk_type != LIBVMDK_DISK_TYPE_VMFS_FLAT_PRE_ALLOCATED )
	 && ( disk_type != LIBVMDK_DISK_TYPE_VMFS_FLAT_ZEROED )
	 && ( disk_type != LIBVMDK_DISK_TYPE_VMFS_SPARSE )
	 && ( disk_type != LIBVMDK_DISK_TYPE_VMFS_SPARSE_THIN ) )
	{
		/* Unsupported disk type
		 */
		result = 0;
	}
	else
	{
		result = libvmdk_handle_get_parent_content_identifier(
			  vmdk_handle,
			  &parent_content_identifier,
			  error );

		if( result == -1 )
		{
			libcerror_error_set(
			 error,
			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
			 "%s: unable to retrieve parent content identifier.",
			 function );

			goto on_error;
		}
		else if( ( result != 0 )
		      && ( parent_content_identifier != 0xffffffffUL ) )
		{
			result = mount_handle_open_parent(
			          mount_handle,
			          vmdk_handle,
			          error );

			if( result == -1 )
			{
				libcerror_error_set(
				 error,
				 LIBCERROR_ERROR_DOMAIN_IO,
				 LIBCERROR_IO_ERROR_OPEN_FAILED,
				 "%s: unable to open parent handle.",
				 function );

				goto on_error;
			}
		}
		else
		{
			result = 1;
		}
	}
	if( result == 0 )
	{
		if( libvmdk_handle_close(
		     vmdk_handle,
		     error ) != 0 )
		{
