		 LIBCERROR_RUNTIME_ERROR_APPEND_FAILED,
		 "%s: unable to append handle to file system.",
		 function );

		goto on_error;
	}
	return( 1 );

on_error:
	if( vmdk_handle != NULL )
	{
		libvmdk_handle_free(
		 &vmdk_handle,
		 NULL );
	}
	return( -1 );
