+/* Opens a snapshot chain at a specific snapshot index
+ * Returns 1 if successful or -1 on error
+ */
+int libvmdk_internal_handle_open_snapshot_chain(
+     libvmdk_handle_t *handle,
+     const system_character_t *filename,
+     int snapshot_index,
+     int access_flags,
+     libcerror_error_t **error )
+{
+	libbfio_pool_t *unused_file_io_pool             = NULL;
+	libvmdk_handle_t *current_handle                 = NULL;
+	libvmdk_handle_t *parent_handle                  = NULL;
+	libvmdk_internal_handle_t *internal_handle       = NULL;
+	system_character_t *parent_path                  = NULL;
+	static char *function                            = "libvmdk_internal_handle_open_snapshot_chain";
+	size_t parent_path_size                          = 0;
+	uint32_t content_identifier                      = 0;
+	int parent_snapshot_index                        = 0;
+	int result                                       = 0;
+
+	if( handle == NULL )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
+		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
+		 "%s: invalid handle.",
+		 function );
+
+		return( -1 );
+	}
+	internal_handle = (libvmdk_internal_handle_t *) handle;
+
+	if( filename == NULL )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
+		 LIBCERROR_ARGUMENT_ERROR_INVALID_VALUE,
+		 "%s: invalid filename.",
+		 function );
+
+		return( -1 );
+	}
+	if( snapshot_index < 0 )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_ARGUMENTS,
+		 LIBCERROR_ARGUMENT_ERROR_VALUE_OUT_OF_BOUNDS,
+		 "%s: snapshot index value out of bounds.",
+		 function );
+
+		return( -1 );
+	}
+	if( internal_handle->descriptor_file != NULL )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_RUNTIME,
+		 LIBCERROR_RUNTIME_ERROR_VALUE_ALREADY_SET,
+		 "%s: invalid handle - descriptor file already set.",
+		 function );
+
+		return( -1 );
+	}
+#if defined( HAVE_WIDE_SYSTEM_CHARACTER )
+	result = libvmdk_handle_open_wide(
+	          handle,
+	          filename,
+	          access_flags,
+	          error );
+#else
+	result = libvmdk_handle_open(
+	          handle,
+	          filename,
+	          access_flags,
+	          error );
+#endif
+	if( result != 1 )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_IO,
+		 LIBCERROR_IO_ERROR_OPEN_FAILED,
+		 "%s: unable to open snapshot.",
+		 function );
+
+		goto on_error;
+	}
+	if( libvmdk_handle_open_extent_data_files(
+	     handle,
+	     error ) != 1 )
+	{
+		libcerror_error_set(
+		 error,
+		 LIBCERROR_ERROR_DOMAIN_IO,
+		 LIBCERROR_IO_ERROR_OPEN_FAILED,
+		 "%s: unable to open snapshot extent data files.",
+		 function );
+
+		goto on_error;
+	}
+	current_handle = handle;
+
+	for( parent_snapshot_index = snapshot_index - 1;
+	     parent_snapshot_index >= 0;
+	     parent_snapshot_index-- )
+	{
+		if( libvmdk_snapshot_initialize(
+		     (libvmdk_snapshot_t **) &parent_handle,
+		     error ) != 1 )
+		{
+			break;
+		}
+		libvmdk_snapshot_free(
+		 (libvmdk_snapshot_t **) &parent_handle,
+		 NULL );
+
+		if( libvmdk_handle_initialize(
+		     &parent_handle,
+		     error ) != 1 )
+		{
+			libcerror_error_set(
+			 error,
+			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
+			 LIBCERROR_RUNTIME_ERROR_INITIALIZE_FAILED,
+			 "%s: unable to initialize parent handle.",
+			 function );
+
+			goto on_error;
+		}
+		if( libvmdk_handle_get_parent_filename(
+		     (libvmdk_internal_handle_t *) handle,
+		     &parent_path,
+		     &parent_path_size,
+		     error ) != 1 )
+		{
+			libcerror_error_set(
+			 error,
+			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
+			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
+			 "%s: unable to resolve parent snapshot filename.",
+			 function );
+
+			goto on_error;
+		}
+		if( libvmdk_handle_open(
+		     parent_handle,
+		     parent_path,
+		     access_flags,
+		     error ) != 1 )
+		{
+			libcerror_error_set(
+			 error,
+			 LIBCERROR_ERROR_DOMAIN_IO,
+			 LIBCERROR_IO_ERROR_OPEN_FAILED,
+			 "%s: unable to open parent snapshot.",
+			 function );
+
+			goto on_error;
+		}
+		if( libvmdk_handle_get_content_identifier(
+		     parent_handle,
+		     &content_identifier,
+		     error ) != 1 )
+		{
+			libcerror_error_set(
+			 error,
+			 LIBCERROR_ERROR_DOMAIN_RUNTIME,
+			 LIBCERROR_RUNTIME_ERROR_GET_FAILED,
+			 "%s: unable to retrieve parent snapshot content identifier.",
+			 function );
+
+			goto on_error;
+		}
+		if( libvmdk_handle_open_extent_data_files(
+		     parent_handle,
+		     error ) != 1 )
+		{
+			libcerror_error_set(
+			 error,
+			 LIBCERROR_ERROR_DOMAIN_IO,
+			 LIBCERROR_IO_ERROR_OPEN_FAILED,
+			 "%s: unable to open parent snapshot extent data files.",
+			 function );
+
+			goto on_error;
+		}
+		if( libvmdk_handle_set_parent_handle(
+		     current_handle,
+		     parent_handle,
+		     error ) != 1 )
+		{
